"""Exercise both shipped CLIs against the real API, in both directions."""

import os
import queue
import socket
import subprocess
import threading
import time
from contextlib import ExitStack, contextmanager
from pathlib import Path
from uuid import UUID

ROOT = Path(__file__).resolve().parents[1]


class Terminal:
    def __init__(self, command, cwd):
        self.lines = queue.Queue()
        self.transcript = []
        self.process = subprocess.Popen(
            command,
            cwd=cwd,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            env={**os.environ, "PYTHONUNBUFFERED": "1"},
        )
        self.reader = threading.Thread(target=self._read, daemon=True)
        self.reader.start()

    def _read(self):
        for line in self.process.stdout:
            self.transcript.append(line.rstrip())
            self.lines.put(line.rstrip())

    def send(self, command):
        self.process.stdin.write(command + "\n")
        self.process.stdin.flush()

    def expect(self, fragment, timeout=10):
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            try:
                line = self.lines.get(timeout=max(0.01, deadline - time.monotonic()))
            except queue.Empty:
                break
            if fragment in line:
                return line
        raise AssertionError(f"Missing {fragment!r}; transcript: {self.transcript}")

    def close(self):
        try:
            if self.process.poll() is None:
                self.send("/quit")
                self.process.wait(timeout=5)
        finally:
            if self.process.poll() is None:
                self.process.kill()
                self.process.wait(timeout=5)
            self.reader.join(timeout=2)
            self.process.stdin.close()
            self.process.stdout.close()


@contextmanager
def server():
    with socket.socket() as listener:
        listener.bind(("127.0.0.1", 0))
        port = listener.getsockname()[1]
    command = [
        "uv",
        "run",
        "--frozen",
        "python",
        "-c",
        (
            "from chat.api import create_app; from chat.server import create_server; "
            f"create_server(create_app(), host='127.0.0.1', port={port}).run()"
        ),
    ]
    process = subprocess.Popen(
        command, cwd=ROOT / "api", stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
    )
    try:
        deadline = time.monotonic() + 10
        while True:
            try:
                with socket.create_connection(("127.0.0.1", port), timeout=0.1):
                    break
            except OSError:
                assert process.poll() is None, "API process exited during startup"
                assert time.monotonic() < deadline, "API startup timed out"
                time.sleep(0.02)
        yield f"ws://127.0.0.1:{port}/ws"
    finally:
        process.terminate()
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=5)


def test_python_and_rust_exchange_messages():
    with server() as url, ExitStack() as cleanup:
        python = Terminal(
            ["uv", "run", "--frozen", "chat-python", "--url", url],
            ROOT / "python-client",
        )
        cleanup.callback(python.close)
        rust = Terminal(
            [str(ROOT / "rust-client/target/debug/chat-rust"), "--url", url],
            ROOT / "rust-client",
        )
        cleanup.callback(rust.close)
        for client, name in [(python, "python_user"), (rust, "rust_user")]:
            client.send(f"/connect {name}")
            # Status is local; poll until the asynchronous login completes.
            deadline = time.monotonic() + 10
            while True:
                client.send("/status")
                line = client.expect("Session:")
                if "logged in" in line:
                    break
                assert time.monotonic() < deadline, client.transcript
                time.sleep(0.05)
        for sender, recipient, name, message in [
            (python, rust, "rust_user", "hello from Python 🌎  two spaces"),
            (rust, python, "python_user", "hello from Rust 🦀  two spaces"),
        ]:
            sender.send(f"/send {name} {message}")
            UUID(sender.expect("✓ Accepted ").split("✓ Accepted ", 1)[1].strip())
            recipient.expect(message)
        for client in (python, rust):
            assert not any("delivery_receipt" in line for line in client.transcript)
            client.send("/status")
            client.expect("Session: logged in")
use chrono::{DateTime, Utc};
use futures_util::{SinkExt, StreamExt};
use serde_json::{Value, json};
use std::{process::Stdio, time::Duration};
use tokio::{
    io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader, Lines},
    net::{TcpListener, TcpStream},
    process::{Child, ChildStdin, ChildStdout, Command},
    time::timeout,
};
use tokio_tungstenite::{WebSocketStream, accept_async, tungstenite::Message};
use uuid::Uuid;

const WAIT: Duration = Duration::from_secs(5);
type Peer = WebSocketStream<TcpStream>;

struct Cli {
    child: Child,
    input: ChildStdin,
    output: Lines<BufReader<ChildStdout>>,
    transcript: String,
}

impl Cli {
    async fn start(url: &str) -> Self {
        let mut child = Command::new(env!("CARGO_BIN_EXE_chat-rust"))
            .args(["--url", url])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true)
            .spawn()
            .unwrap();
        let input = child.stdin.take().unwrap();
        let output = BufReader::new(child.stdout.take().unwrap()).lines();
        let mut cli = Self {
            child,
            input,
            output,
            transcript: String::new(),
        };
        cli.until("Chat ready.").await;
        cli
    }

    async fn command(&mut self, command: &str) {
        self.input
            .write_all(format!("{command}\n").as_bytes())
            .await
            .unwrap();
        self.input.flush().await.unwrap();
    }

    async fn until(&mut self, expected: &str) -> String {
        let result = timeout(WAIT, async {
            loop {
                let line = self
                    .output
                    .next_line()
                    .await
                    .unwrap()
                    .expect("CLI output ended");
                self.transcript.push_str(&line);
                self.transcript.push('\n');
                if line.contains(expected) {
                    return line;
                }
            }
        })
        .await;
        result.unwrap_or_else(|_| panic!("Missing {expected:?}; output:\n{}", self.transcript))
    }

    async fn quit(&mut self) {
        self.command("/quit").await;
        assert!(
            timeout(WAIT, self.child.wait())
                .await
                .unwrap()
                .unwrap()
                .success()
        );
    }
}

async fn listener() -> (TcpListener, String) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("ws://{}/ws", listener.local_addr().unwrap());
    (listener, url)
}

async fn accept(listener: &TcpListener) -> Peer {
    let (stream, _) = timeout(WAIT, listener.accept()).await.unwrap().unwrap();
    timeout(WAIT, accept_async(stream)).await.unwrap().unwrap()
}

async fn frame(peer: &mut Peer) -> Message {
    timeout(WAIT, peer.next()).await.unwrap().unwrap().unwrap()
}

async fn request(peer: &mut Peer, action: &str) -> Value {
    let frame = frame(peer).await;
    let Message::Text(text) = frame else {
        panic!("Expected request, received {frame:?}")
    };
    let request: Value = serde_json::from_str(&text).unwrap();
    assert_eq!(request["type"], action);
    Uuid::parse_str(request["correlation_id"].as_str().unwrap()).unwrap();
    assert!(request["data"].is_object());
    request
}

async fn reply(peer: &mut Peer, value: Value) {
    peer.send(Message::Text(value.to_string().into()))
        .await
        .unwrap();
}

async fn login(cli: &mut Cli, listener: &TcpListener, command: &str, name: &str) -> Peer {
    cli.command(command).await;
    let mut peer = accept(listener).await;
    let request = request(&mut peer, "login").await;
    assert_eq!(request["data"], json!({"name": name}));
    reply(
        &mut peer,
        json!({"type":"login_ok", "correlation_id": request["correlation_id"],
        "data":{"id":Uuid::new_v4(), "name":name}}),
    )
    .await;
    cli.until(&format!("Logged in as {name}")).await;
    peer
}

fn message(id: Uuid, text: &str) -> Value {
    json!({"id":id, "sender_id":Uuid::new_v4(), "recipient_id":Uuid::new_v4(),
        "text":text, "client_sent_at":0, "server_received_at":"2026-11-08T12:00:00Z",
        "recipient_received_at":null, "server_ack_received_at":null})
}

